<section class="portal-card"><h1>My Service Book / මගේ සේවා පොත</h1><p id="customerWelcome" class="portal-muted"></p>
<div id="vehicleSummary" class="vehicle-summary" hidden></div><form id="portalSearch"><div class="portal-grid"><div><label for="portalVehicle">My Vehicle / මගේ වාහනය</label><select id="portalVehicle"><option value="">Choose a vehicle / වාහනයක් තෝරන්න</option></select></div><div><label for="portalSerial">Part Serial Number / කොටසේ අනුක්‍රමික අංකය</label><input id="portalSerial" maxlength="100" placeholder="e.g. 00123ABC" autocomplete="off"></div></div>
<p class="portal-muted">Choose a vehicle, enter a serial number, or use both.<br>වාහනයක් තෝරන්න, අනුක්‍රමික අංකයක් ඇතුළත් කරන්න, නැත්නම් දෙකම භාවිත කරන්න.</p>
<button id="portalSearchButton" type="submit">Search / සොයන්න</button></form><div id="portalStatus" class="portal-status" role="status" aria-live="polite"></div></section>
<section class="portal-card" id="warrantyCard" hidden><h2>Warranty / වගකීම් විස්තර</h2><div id="portalWarranties" aria-live="polite"></div><p class="portal-muted">Only workshop-approved warranty records appear here. Contact CCS Solutions for eligibility confirmation.<br>වැඩපොළ අනුමත කළ වගකීම් පමණක් මෙහි පෙන්වයි.</p></section>
<section class="portal-card"><h2>Service Records / සේවා වාර්තා</h2><div id="portalResults"><p class="portal-muted">Choose a vehicle or search a serial number.</p></div><div class="portal-pages"><button id="portalPrevious" type="button" hidden>← Previous</button><button id="portalNext" type="button" hidden>Next →</button></div></section>
<section id="portalDetailsCard" class="portal-card" hidden><h2>Module Details / මොඩියුල විස්තර</h2><p id="portalDetailsHeading"></p><div class="portal-scroll"><table><thead><tr><th>No.</th><th>Serial Number</th><th>Voltage (V)</th></tr></thead><tbody id="portalModules"></tbody></table></div></section>
<script>
(()=>{
 const urls={{ Illuminate\Support\Js::from(['me'=>route('customer.api.me'),'vehicles'=>route('customer.api.vehicles'),'search'=>route('customer.api.search'),'base'=>url('/customer/api'),'login'=>route('customer.login')]) }};
 const $=id=>document.getElementById(id),status=$('portalStatus'),select=$('portalVehicle');
 let busy=false,detailVersion=0,loadVersion=0,warrantyVersion=0;
 function message(text,error=false){status.textContent=text;status.className='portal-status '+(error?'portal-error':'portal-muted');}
 async function get(url){const target=new URL(url,location.href);if(target.origin!==location.origin)throw Error('Invalid API location.');const response=await fetch(target,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(response.status===401){location.href=urls.login;throw Error('Please sign in again.');}const body=await response.json();if(!response.ok)throw Error(body.message||'Unable to load records.');return body;}
 function cell(row,text){const td=document.createElement('td');td.textContent=text;row.append(td);}
 async function showDetails(id){const version=++detailVersion;$('portalDetailsCard').hidden=true;message('Loading details…');try{const body=await get(urls.base+'/services/'+id);if(version!==detailVersion)return;const data=body.data;$('portalDetailsHeading').textContent=data.service.registration_number+' · '+data.service.service_date;$('portalModules').replaceChildren();for(const module of data.modules){const row=document.createElement('tr');cell(row,module.position);cell(row,module.serial_number);cell(row,module.voltage===null?'—':module.voltage);$('portalModules').append(row);}$('portalDetailsCard').hidden=false;message('Service details loaded.');}catch(error){if(version===detailVersion)message(error.message,true);}}
 async function load(url){const version=++loadVersion;busy=true;$('portalSearchButton').disabled=true;detailVersion++;$('portalDetailsCard').hidden=true;message('Loading…');try{const body=await get(url);if(version!==loadVersion)return;const area=$('portalResults');area.replaceChildren();if(!body.data.length&&!(body.parts||[]).length){const text=document.createElement('p');text.textContent='No matching service records for your vehicles. / ඔබගේ වාහන සඳහා ගැළපෙන සේවා වාර්තා නැත.';area.append(text);}for(const record of body.data){const row=document.createElement('div');row.className='portal-result';const description=document.createElement('div');const title=document.createElement('strong');title.textContent=record.registration_number+' · '+record.service_date;const info=document.createElement('div');info.className='portal-muted';info.textContent=record.job_number+' · '+(record.mileage_km??'—')+' km · '+record.module_count+' modules';description.append(title,info);const button=document.createElement('button');button.type='button';button.textContent='View / බලන්න';button.addEventListener('click',()=>showDetails(record.id));row.append(description,button);area.append(row);}for(const part of body.parts||[]){const row=document.createElement('div');row.className='portal-result';const info=document.createElement('div');const title=document.createElement('strong');title.textContent=part.description+' · '+part.serial_number;const note=document.createElement('div');note.className='portal-muted';note.textContent=part.registration_number+' · '+part.job_number+' · '+(part.recorded_at||'')+' · Linked part';info.append(title,note);row.append(info);area.append(row);} for(const [id,key] of [['portalPrevious','previous'],['portalNext','next']]){const button=$(id);button.hidden=!body.links[key];button.onclick=()=>load(body.links[key]);}message(body.meta.total+' service records · '+(body.parts||[]).length+' linked parts shown.');}catch(error){if(version===loadVersion)message(error.message,true);}finally{if(version===loadVersion){busy=false;$('portalSearchButton').disabled=false;}}}
 async function warranty(vehicle){
  const version=++warrantyVersion;$('warrantyCard').hidden=!vehicle;$('portalWarranties').textContent='Loading…';if(!vehicle)return;
  try{const body=await get(urls.base+'/vehicles/'+vehicle+'/warranties');if(version!==warrantyVersion)return;const area=$('portalWarranties');area.replaceChildren();
   if(!body.data.length){area.textContent='No approved warranty details are available. / අනුමත වගකීම් විස්තර දැනට නොමැත.';return;}
   for(const record of body.data){const card=document.createElement('div');card.className='warranty-record';const title=document.createElement('strong');title.textContent=record.name+(record.covered_serial?' · '+record.covered_serial:'');const dates=document.createElement('p');dates.textContent='From: '+record.starts_on+' · Until: '+(record.expires_on||'Not specified')+' · Mileage limit: '+(record.mileage_limit_km===null?'Not specified':record.mileage_limit_km+' km')+' · Basis: '+(record.limit_basis||'Confirm with workshop');card.append(title,dates);if(record.card_status){const status=document.createElement('p');status.textContent=record.card_status.card_number+' · '+({no_warranty:'No warranty',not_started:'Not started',time_elapsed:'Time limit elapsed',time_remaining:'Time remaining',no_time_limit:'See agreed mileage / conditions'}[record.card_status.state]||record.card_status.state)+(record.card_status.remaining_days===null?'':' · '+record.card_status.remaining_days+' days remaining')+(record.card_status.remaining_km===null?'':' · '+record.card_status.remaining_km+' km remaining');card.append(status);}if(record.free_services){const benefits=document.createElement('p');benefits.textContent='Free services: '+record.free_services.used+' / '+record.free_services.included+' · Remaining: '+record.free_services.remaining;card.append(benefits);}if(record.terms){const terms=document.createElement('p');terms.style.whiteSpace='pre-wrap';terms.textContent=typeof record.terms==='string'?record.terms:JSON.stringify(record.terms);card.append(terms);}area.append(card);}
  }catch(error){if(version===warrantyVersion)$('portalWarranties').textContent=error.message;}
 }
 function vehicleChanged(){const option=select.selectedOptions[0];$('vehicleSummary').hidden=!select.value;$('vehicleSummary').textContent=select.value?option.textContent:'';warranty(select.value);if(select.value){$('portalSerial').value='';load(urls.base+'/vehicles/'+select.value+'/history');}else{++loadVersion;++detailVersion;$('portalDetailsCard').hidden=true;$('portalResults').replaceChildren();$('portalPrevious').hidden=true;$('portalNext').hidden=true;message('Choose a vehicle or search a serial number.');$('portalSearchButton').disabled=false;}}
 select.addEventListener('change',vehicleChanged);
 $('portalSearch').addEventListener('submit',event=>{event.preventDefault();const serial=$('portalSerial').value.trim(),vehicle=select.value;if(!serial&&!vehicle){message('Choose a vehicle or enter a serial number.',true);return;}if(!serial){load(urls.base+'/vehicles/'+vehicle+'/history');return;}const query=new URLSearchParams({serial_number:serial});if(vehicle)query.set('registration_number',select.selectedOptions[0].dataset.plate);load(urls.search+'?'+query);});
 Promise.all([get(urls.me),get(urls.vehicles)]).then(([me,vehicles])=>{$('customerWelcome').textContent=me.data.name+' · '+me.data.customer_code;for(const vehicle of vehicles.data){const option=document.createElement('option');option.value=vehicle.id;option.dataset.plate=vehicle.registration_number;option.textContent=vehicle.registration_number+' · '+vehicle.make+' '+vehicle.model+(vehicle.manufacture_year?' · '+vehicle.manufacture_year:'');select.append(option);}if(!vehicles.data.length)message('No vehicles linked to this account. Contact the workshop.');else if(vehicles.data.length===1){select.value=String(vehicles.data[0].id);vehicleChanged();}else message('Choose your vehicle to see its service book. / ඔබගේ වාහනය තෝරන්න.');}).catch(error=>message(error.message,true));
})();
</script>
@endsection
